SELECT sh.schedule_header_id, c.contract_no, sh.payment_stage, sh.schedule_regime, sh.schedule_purpose, sh.schedule_version_no, sh.status, sh.active_yn, sh.generated_at, sh.generation_reason, COUNT(sl.schedule_line_id) AS line_count, COALESCE(SUM(sl.expected_amount), 0) AS expected_total, CONCAT(pv.policy_code,' v',pv.version_no) AS policy_version_label FROM schedule_header sh JOIN insurance_contract c ON c.contract_id = sh.contract_id JOIN policy_version pv ON pv.policy_version_id = sh.policy_version_id LEFT JOIN schedule_line sl ON sl.schedule_header_id = sh.schedule_header_id
AND c.contract_no LIKE CONCAT('%', #{condition.contractNo}, '%')
AND sh.payment_stage = #{condition.stage}
AND sh.schedule_regime = #{condition.regime}
AND sh.schedule_purpose = #{condition.purpose}
AND sh.status = #{condition.status}
GROUP BY sh.schedule_header_id, c.contract_no, pv.policy_code, pv.version_no ORDER BY sh.schedule_header_id DESC LIMIT #{size} OFFSET #{offset}

SELECT sh.schedule_header_id, c.contract_no, sh.payment_stage, sh.schedule_regime, sh.schedule_purpose, sh.schedule_version_no, sh.status, sh.active_yn, sh.generated_at, sh.generation_reason, COUNT(sl.schedule_line_id) AS line_count, COALESCE(SUM(sl.expected_amount), 0) AS expected_total, CONCAT(pv.policy_code, ' v', pv.version_no) AS policy_version_label FROM schedule_header sh JOIN insurance_contract c ON c.contract_id = sh.contract_id JOIN policy_version pv ON pv.policy_version_id = sh.policy_version_id LEFT JOIN schedule_line sl ON sl.schedule_header_id = sh.schedule_header_id
AND c.contract_no LIKE CONCAT('%', #{condition.contractNo}, '%') AND sh.payment_stage = #{condition.stage} AND sh.schedule_regime = #{condition.regime} AND sh.schedule_purpose = #{condition.purpose} AND sh.status = #{condition.status}
GROUP BY sh.schedule_header_id, c.contract_no, pv.policy_code, pv.version_no ORDER BY sh.schedule_header_id DESC

SELECT
    COUNT(*)
FROM
    schedule_header sh
JOIN
    insurance_contract c
        ON c.contract_id = sh.contract_id


        AND c.contract_no
        LIKE CONCAT('%', #{condition.contractNo}, '%')



        AND sh.payment_stage = #{condition.stage}



        AND sh.schedule_regime = #{condition.regime}



        AND sh.schedule_purpose = #{condition.purpose}



        AND sh.status = #{condition.status}

