SELECT policy_version_id
FROM fgc.schedule_header
WHERE contract_id = #{contractId}
  AND payment_stage = #{paymentStage}
  AND schedule_purpose = 'OPERATIONAL'
  AND active_yn = TRUE

SELECT COALESCE(MAX(schedule_version_no), 0) + 1
FROM fgc.schedule_header
WHERE contract_id = #{contractId}
  AND payment_stage = #{paymentStage}
  AND schedule_purpose = 'OPERATIONAL'

